-- 3b. Middle Way Pseudocode Algorithms (The Discrete Machine Library)
INSERT INTO pseudocode_algorithms (
  id, algo_key, func_name, name, badge, category, algo_kind, signature, summary, domain, scaffold_key, primitives, tree_complexity, dyadic_complexity, code, explanation, example, presets
) OVERRIDING SYSTEM VALUE VALUES
  (1, 'simpler_options', 'SimplerOptions', 'Extract Simpler Tree Ancestor Options', 'Tree Decomposition', 'tree_topology', 'predicate', 'Node → (Set of Node × Set of Node)', 'Extracts all ancestral prefixes of node X born on earlier days, partitioned into left options (< X) and right options (> X).', 'X ∈ {+, -}* (Tree Node) ⟹ (XL, XR) where each option has birthday < birthday(X)', 'Tree1_is_well_ordered', ARRAY['EmptySet()', 'Insert(set, item)', 'length(X)', 'prefix < X (tree order)', 'X[0 .. i] (proper prefix)']::text[], 'O(d) prefix extractions, where d is the birthday (string depth) of node X', 'O(1) sign-string prefix slice and set insertion', 'rule SimplerOptions(X: Node) : (Set of Node, Set of Node) ≔
var
    XL, XR: Set of Node;
    i: Integer;
    prefix: Node;
begin
    XL := EmptySet();
    XR := EmptySet();

    // All proper prefixes are numbers born on earlier days
    for i := 0 to length(X) - 1 do
    begin
        prefix := X[0 .. i];
        if prefix < X then
            Insert(XL, prefix)
        else
            Insert(XR, prefix);
    end;

    return (XL, XR);
end;', '["Every tree node X is identified by its sign sequence of + and - steps from the root [].","The \"options\" of X are strictly its ancestral prefixes born on earlier days.","Prefixes smaller than X form the left set XL; prefixes greater form the right set XR.","Guarantees finite inductive reduction by well-founded induction on birthday depth."]'::jsonb, '{"inputs":["X = [+ -] (1/2, born Day 2)"],"steps":["Prefix length 0: [] (0) < [+ -] ⟹ Insert([], XL)","Prefix length 1: [+] (1) > [+ -] ⟹ Insert([+], XR)"],"result":"XL = { [] }, XR = { [+] }"}'::jsonb, '[{"id":"simpler_half","label":"SimplerOptions(1/2) ⟹ {0}, {1}","args":["+-"]}]'::jsonb),
  (2, 'cut', 'Cut', 'Conway Cut: Earliest Birthday Node Between Bounds', 'Tree Simplicity', 'tree_topology', 'operation', '(Node × Node) → Node', 'Finds the unique earliest-born (simplest) Conway tree node strictly between a lower bound and upper bound by binary walking from root [].', 'leftBound, rightBound ∈ {+, -}* with leftBound < rightBound ⟹ candidate Node', 'D_w_dense_in_R_w', ARRAY['candidate ++ "+" (branch right)', 'candidate ++ "-" (branch left)', '<= (tree order comparison)', '>= (tree order comparison)']::text[], 'O(d) tree walk from root [] to the simplest intermediate node born on day d', 'O(1) binary mediant branch navigation', 'rule Cut(leftBound: Node, rightBound: Node) : Node ≔
var
    candidate: Node;
begin
    // Walk down the binary tree from the root []
    candidate := [];
    while (candidate <= leftBound) or (candidate >= rightBound) do
    begin
        if candidate <= leftBound then
            candidate := candidate ++ ''+''      // Branch right to grow
        else
            candidate := candidate ++ ''-'';     // Branch left to shrink
    end;
    return candidate;  // Unique simplest node strictly between bounds
end;', '["The Conway cut embodies the Simplicity Theorem: between any two surreal numbers lies a unique simplest number born on the earliest day.","Begins at the root node [] (0).","If candidate ≤ leftBound, branches right (+) to grow larger.","If candidate ≥ rightBound, branches left (-) to shrink smaller.","Terminates at the unique simplest sign sequence strictly between leftBound and rightBound."]'::jsonb, '{"inputs":["leftBound = 1 ([+])","rightBound = 1&1/2 ([+ + -])"],"steps":["candidate = [] (0) <= 1 ⟹ branch right (+), candidate := [+]","candidate = [+] (1) <= 1 ⟹ branch right (+), candidate := [+ +]","candidate = [+ +] (2) >= 1&1/2 ⟹ branch left (-), candidate := [+ + -]"],"result":"Cut(1, 1&1/2) = [+ + -] (1&1/4)"}'::jsonb, '[{"id":"cut_bounds","label":"Cut(1, 1&1/2) ⟹ 1&1/4","args":["+","++-"]}]'::jsonb),
  (3, 'conway_add', 'ConwayAdd', 'Conway Inductive Addition', 'Tree-Inductive Arithmetic', 'tree_topology', 'operation', '(Node × Node) → Node', 'Evaluates the exact sum X + Y of two Conway numbers directly on their tree sign paths by recursive options reduction and Conway cut.', 'X, Y ∈ {+, -}* (Tree Nodes, with [] at root 0)', 'abelian_group', ARRAY['SimplerOptions(X)', 'Cut(L, R)', 'ConwayAdd(x, y) [recursive]', 'EmptySet()', 'Insert(set, item)', 'Maximum(set)', 'Minimum(set)']::text[], 'O(4^d) recursive option calls (explodes exponentially with birthday d)', 'O(1) aligned bit-shift and 32-bit integer add in the ring (𝔻, +, ·)', 'rule ConwayAdd(X: Node, Y: Node) : Node ≔
var
    XL, XR, YL, YR: Set of Node;
    leftResults, rightResults: Set of Node;
    maxLeft, minRight: Node;
begin
    // 1. Decompose both nodes into their simpler tree ancestors
    (XL, XR) := SimplerOptions(X);
    (YL, YR) := SimplerOptions(Y);

    leftResults  := EmptySet();
    rightResults := EmptySet();

    // 2. Recursive cross-additions: (XL + Y) and (X + YL)
    for each xL in XL do Insert(leftResults, ConwayAdd(xL, Y));
    for each yL in YL do Insert(leftResults, ConwayAdd(X, yL));

    // 3. Recursive cross-additions: (XR + Y) and (X + YR)
    for each xR in XR do Insert(rightResults, ConwayAdd(xR, Y));
    for each yR in YR do Insert(rightResults, ConwayAdd(X, yR));

    // 4. Extreme bounds: greatest left option and least right option
    maxLeft  := Maximum(leftResults);
    minRight := Minimum(rightResults);

    // 5. The sum is the simplest node created between the two bounds
    return Cut(maxLeft, minRight);
end;', '["Conway addition recurses over all combinations of simpler ancestors (XL + Y) and (X + YL).","Demonstrates why tree-inductive arithmetic is mathematically fundamental yet computationally explosive.","The Conway cut resolves the final sum as the earliest-born node strictly between maxLeft and minRight."]'::jsonb, '{"inputs":["X = [+ -] (1/2)","Y = [+ - +] (3/4)"],"steps":["XL = { [], [+] }, XR = { [+ - -] }","YL = { [], [+], [+ -] }, YR = { [+ - + -] }","Recurse ConwayAdd on all 5 left options and 2 right options...","max(leftResults) = 1, min(rightResults) = 1&1/2"],"result":"Cut(1, 1&1/2) = [+ + -] (1&1/4)"}'::jsonb, '[{"id":"add_half_three_fourths","label":"ConwayAdd(1/2, 3/4) ⟹ 1&1/4","args":["+-","+-+"]},{"id":"add_one_half","label":"ConwayAdd(1, 1/2) ⟹ 1&1/2","args":["+","+-"]}]'::jsonb),
  (4, 'conway_order', 'ConwayLessEq', 'Conway Inductive Order (X ≤ Y)', 'Tree-Inductive Order', 'tree_topology', 'predicate', '(Node × Node) → 𝔹', 'Determines if node X ≤ Y directly on Conway tree options: no left option of X can be ≥ Y, and no right option of Y can be ≤ X.', 'X, Y ∈ {+, -}* (Tree Nodes) ⟹ 1 if X ≤ Y else 0', 'D_w_is_totally_ordered', ARRAY['SimplerOptions(X)', 'ConwayLessEq(Y, xL) [mutual recursion]', 'ConwayLessEq(yR, X)']::text[], 'O(2^(d_x + d_y)) mutual recursive option evaluations over earlier birthdays', 'O(1) sign comparison and bit alignment in the ordered field (𝔻, ≤)', 'rule ConwayLessEq(X: Node, Y: Node) : Integer ≔
var
    XL, XR, YL, YR: Set of Node;
    xL, yR: Node;
begin
    // 1. Decompose both nodes into simpler ancestral options
    (XL, XR) := SimplerOptions(X);
    (YL, YR) := SimplerOptions(Y);

    // 2. Condition 1: No left option of X is >= Y (i.e. Y <= xL is false)
    for each xL in XL do
    begin
        if ConwayLessEq(Y, xL) = 1 then
            return 0; // Violation found: xL >= Y
    end;

    // 3. Condition 2: No right option of Y is <= X (i.e. yR <= X is false)
    for each yR in YR do
    begin
        if ConwayLessEq(yR, X) = 1 then
            return 0; // Violation found: yR <= X
    end;

    // Satisfies Conway surreal order: X <= Y
    return 1;
end;', '["Conway fundamental inductive definition of order: X ≤ Y ⇔ (∀ xᴸ ∈ Xᴸ, ¬(Y ≤ xᴸ)) ∧ (∀ yᴿ ∈ Yᴿ, ¬(yᴿ ≤ X)).","Base case: 0 ≤ 0 ([] ≤ []) has XL = ∅ and YR = ∅, immediately returning 1 (true).","Inductively generates a total linear order across the entire binary tree without continuous limits or Cauchy sequences.","Grounds the entire field ordering in well-founded induction on birthday depth."]'::jsonb, '{"inputs":["X = [] (0)","Y = [+] (1)"],"steps":["XL = ∅, XR = ∅ for X = []","YL = { [] }, YR = ∅ for Y = [+]","Left loop: XL is empty ⟹ no violation","Right loop: YR is empty ⟹ no violation"],"result":"ConwayLessEq([], [+]) = 1 (0 ≤ 1)"}'::jsonb, '[{"id":"order_zero_one","label":"ConwayLessEq(0, 1) ⟹ True","args":["","+"]},{"id":"order_one_zero","label":"ConwayLessEq(1, 0) ⟹ False","args":["+",""]},{"id":"order_half_threefourths","label":"ConwayLessEq(1/2, 3/4) ⟹ True","args":["+-","+-+"]}]'::jsonb),
  (5, 'conway_sort', 'ConwaySort', 'Conway Total Order Sort', 'Tree-Inductive Sorting', 'tree_topology', 'operation', 'Array of Node → Array of Node', 'Sorts an array of Conway tree nodes into ascending linear order strictly using the recursive ConwayLessEq order predicate.', 'A: Array of Node ⟹ Sorted A such that A[0] ≤ A[1] ≤ ... ≤ A[n-1]', NULL, ARRAY['ConwayLessEq(a, b)', 'A[i] (array indexing)']::text[], 'O(n² · 2^d) inductive option comparisons across array elements', 'O(n log n) standard numeric sort using 64-bit integer compare', 'rule ConwaySort(A: Array of Node, n: Integer) : Array of Node ≔
var
    i, j: Integer;
    key: Node;
begin
    // Insertion sort grounded strictly on Conway inductive order
    for i := 1 to n - 1 do
    begin
        key := A[i];
        j := i - 1;

        // Shift elements greater than key to the right
        while (j >= 0) and (ConwayLessEq(key, A[j]) = 1) do
        begin
            A[j + 1] := A[j];
            j := j - 1;
        end;
        A[j + 1] := key;
    end;

    return A;
end;', '["Demonstrates that Conway recursive order defines a true total ordering on any finite collection of surreal numbers.","Uses insertion sort where every pairwise order decision invokes the inductive ConwayLessEq predicate.","Shows how abstract combinatorial game options organize into a strict linear sequence from least to greatest."]'::jsonb, '{"inputs":["A = [1, -1, 1/2, 0, -1/2]","n = 5"],"steps":["Compare key -1 with 1: -1 ≤ 1 ⟹ shift","Compare key 1/2 with 1: 1/2 ≤ 1 ⟹ insert after 0","Final sorted array satisfies Conway order at every step"],"result":"ConwaySort(A, 5) = [-1, -1/2, 0, 1/2, 1]"}'::jsonb, '[{"id":"sort_standard_5","label":"ConwaySort([1, -1, 1/2, 0, -1/2], 5)","args":[["+","-","+-","","-+"],5]},{"id":"sort_dyadics_4","label":"ConwaySort([3/4, 1/4, 1/2, 0], 4)","args":[["+-+","+--","+-",""],4]}]'::jsonb),
  (6, 'conway_sub', 'ConwaySub', 'Conway Inductive Subtraction', 'Tree-Inductive Arithmetic', 'tree_topology', 'operation', '(Node × Node) → Node', 'Evaluates the exact difference X - Y of two Conway numbers as X + (-Y) via Conway tree negation and addition.', 'X, Y ∈ {+, -}* (Tree Nodes) ⟹ X - Y', NULL, ARRAY['ConwayNeg(Y)', 'ConwayAdd(X, -Y)']::text[], 'O(4^d) option tree expansion inherited from ConwayAdd', 'O(1) aligned bit-shift and integer subtraction in the ring (𝔻, +, ·)', 'rule ConwaySub(X: Node, Y: Node) : Node ≔
var
    negY: Node;
begin
    // Subtraction is addition of the tree negation: X - Y = X + (-Y)
    negY := ConwayNeg(Y);
    return ConwayAdd(X, negY);
end;', '["Conway subtraction reduces directly to addition with the sign-inverted tree node.","Reflects the right-hand argument Y across the root 0 (+ <-> -).","Preserves the group inversion law in the surreal number field."]'::jsonb, '{"inputs":["X = [+ + -] (1&1/4)","Y = [+ - +] (3/4)"],"steps":["ConwayNeg([+ - +]) = [- + -] (-3/4)","ConwayAdd(1&1/4, -3/4) = 1/2"],"result":"ConwaySub(1&1/4, 3/4) = [+ -] (1/2)"}'::jsonb, '[{"id":"sub_demo_1","label":"ConwaySub(1&1/4, 3/4) ⟹ 1/2","args":["++-","+-+"]},{"id":"sub_demo_2","label":"ConwaySub(1, 1/2) ⟹ 1/2","args":["+","+-"]}]'::jsonb),
  (7, 'conway_mul', 'ConwayMul', 'Conway Inductive Multiplication', 'Tree-Inductive Arithmetic', 'tree_topology', 'operation', '(Node × Node) → Node', 'Evaluates the exact product X · Y of two Conway numbers directly on their tree sign paths via 4-way recursive cross options and Conway cut.', 'X, Y ∈ {+, -}* (Tree Nodes) ⟹ X · Y', 'field_structure', ARRAY['SimplerOptions(X)', 'ConwayAdd(a, b)', 'ConwaySub(a, b)', 'ConwayMul(a, b) [recursive]', 'Cut(L, R)']::text[], 'Hyper-exponential option explosion: each recursive step branches into 4 products, 2 additions, and 1 subtraction', 'O(1) single integer multiplication and denominator bit addition: (m₁/2^e₁) · (m₂/2^e₂) = (m₁·m₂)/2^(e₁+e₂)', 'rule ConwayMul(X: Node, Y: Node) : Node ≔
var
    XL, XR, YL, YR: Set of Node;
    leftResults, rightResults: Set of Node;
    term, maxLeft, minRight: Node;
begin
    // 1. Decompose both nodes into ancestral options
    (XL, XR) := SimplerOptions(X);
    (YL, YR) := SimplerOptions(Y);

    leftResults  := EmptySet();
    rightResults := EmptySet();

    // 2. Left options: (xL · Y) + (X · yL) - (xL · yL)
    for each xL in XL do
        for each yL in YL do
        begin
            term := ConwayAdd(ConwayMul(xL, Y), ConwayMul(X, yL));
            Insert(leftResults, ConwaySub(term, ConwayMul(xL, yL)));
        end;

    // (xR · Y) + (X · yR) - (xR · yR)
    for each xR in XR do
        for each yR in YR do
        begin
            term := ConwayAdd(ConwayMul(xR, Y), ConwayMul(X, yR));
            Insert(leftResults, ConwaySub(term, ConwayMul(xR, yR)));
        end;

    // 3. Right options: (xL · Y) + (X · yR) - (xL · yR)
    for each xL in XL do
        for each yR in YR do
        begin
            term := ConwayAdd(ConwayMul(xL, Y), ConwayMul(X, yR));
            Insert(rightResults, ConwaySub(term, ConwayMul(xL, yR)));
        end;

    // (xR · Y) + (X · yL) - (xR · yL)
    for each xR in XR do
        for each yL in YL do
        begin
            term := ConwayAdd(ConwayMul(xR, Y), ConwayMul(X, yL));
            Insert(rightResults, ConwaySub(term, ConwayMul(xR, yL)));
        end;

    // 4. Resolve simplest intermediate node between bounds
    maxLeft  := Maximum(leftResults);
    minRight := Minimum(rightResults);
    return Cut(maxLeft, minRight);
