) OVERRIDING SYSTEM VALUE VALUES
  (1, 'fs_newtonian_mechanics', 'newtonian_mechanics', 'kinematics_and_dynamics', 'physics', 'theorem', NULL, 'theorem', NULL, 'physics', 'law', 'boundary_law', 'Newtonian Dynamics & Boundary Acceleration', 'Foundational relation between force, inertia, and momentum conservation on ℝ_ω.', 'F = m · a  ∧  p = m · v', NULL, NULL, 'published', ARRAY['stemNewtonianBridge', 'analysis1DLecture2', 'analysis1DLecture3', 'analysis2DIntro', 'analysis2DLecture2', 'analysis2DLecture3', 'quantumBayesianInferenceLecture1', 'quantumBayesianInferenceLecture2', 'quantumLogicLecture3', 'vectorsLecture1', 'vectorsLecture2', 'vectorsLecture3']::text[]),
  (2, 'fs_free_fall_accel', 'free_fall_accel', 'kinematics_and_dynamics', 'physics', 'directed_equality', 1, 'directed_equality', 10, 'physics', 'scenario', 'boundary_law', 'Uniform Free Fall Kinematics', 'Motion under constant gravitational acceleration g on ℝ_ω.', 'v(t) = v₀ - g · t  ∧  s(t) = v₀·t - (1/2)·g·t²', 'theorem free_fall_stencil (v0 g t : R_w) : v = v0 - g * t', NULL, 'published', ARRAY['stemNewtonianBridge', 'vectorsLecture3']::text[]),
  (3, 'fs_telescoping_ftc', 'telescoping_ftc', 'discrete_analysis', 'math', 'theorem', NULL, 'theorem', NULL, 'math', 'law', 'boundary_law', 'Telescoping Fundamental Theorem of Calculus', 'Discrete interior cancellation collapsing whole-transect sums to boundary differences.', '∑_{k=0}^{n-1} ΔF(k) = F(n) - F(0)', 'theorem telescoping_ftc (F : Nat → R_w) (n : Nat) : hyper_sum (delta F) n = F n - F 0', NULL, 'published', ARRAY['analysis1DLecture3', 'stemHeatDiffusion', 'modelsOverview', 'stemTrigFoundations']::text[]),
  (4, 'fs_work_energy', 'work_energy', 'kinematics_and_dynamics', 'physics', 'directed_equality', 3, 'directed_equality', NULL, 'physics', 'law', 'boundary_law', 'Telescoping Work-Energy Principle', 'Exact cancellation of interior work increments yielding net kinetic energy change.', 'Δ(KE) = (1/2)·m·v² - (1/2)·m·v₀² = ∑_{k=0}^{n-1} F_k · Δx_k', 'theorem work_energy_conservation (m v0 v : R_w) : delta_ke = work_sum', NULL, 'published', ARRAY['stemNewtonianBridge', 'analysis1DLecture3', 'formalStatementsIntro']::text[]),
  (5, 'fs_heat_flux', 'heat_flux', 'kinematics_and_dynamics', 'physics', 'directed_equality', 3, 'directed_equality', 13, 'physics', 'scenario', 'boundary_law', 'Discrete Thermal Diffusion Balance', 'Conservation of thermal energy across discrete boundaries governed by second differences.', 'u_j(t + Δt) = u_j(t) + α · (Δt / Δx²) · [u_{j+1}(t) - 2·u_j(t) + u_{j-1}(t)]', 'theorem heat_stencil_conservation (alpha dt dx u_L u_C u_R : R_w) : u_new = heat_step alpha dt dx u_L u_C u_R', NULL, 'published', ARRAY['stemHeatDiffusion']::text[]),
  (6, 'fs_hyperfinite_derivative', 'hyperfinite_derivative', 'discrete_analysis', 'math', 'directed_equality', NULL, 'directed_equality', 9, 'math', 'law', 'shadow_map', 'Hyperfinite Difference Quotient Derivative', 'Standard part of hyperfinite difference quotients matching classical derivative values.', 'f''(x) = st([f(x + dx) - f(x)] / dx)  for infinitesimal dx ≠ 0', 'theorem nonstandard_derivative (f : R_w → R_w) (x : R_w) (dx : Infinitesimal) : f_prime x = st ((f (x + dx) - f x) / dx)', NULL, 'published', ARRAY['analysis1DLecture1', 'analysis1DLecture2', 'formalStatementsIntro', 'stemExpLogFoundations']::text[]),
  (7, 'fs_complex_step_invariance', 'complex_step_invariance', 'discrete_analysis', 'math', 'directed_equality', NULL, 'directed_equality', NULL, 'math', 'law', 'shadow_map', '2D Complex Step & Modulus Invariance on ℂ_ω', 'Isotropic step invariance of hypercomplex numbers preserving holomorphic geometry.', '|z + dz|² = |z|² + 2·Re(z̄·dz) + |dz|²', 'theorem complex_step_modulus (z dz : C_w) : norm_sq (z + dz) = norm_sq z + 2 * Re (conj z * dz) + norm_sq dz', NULL, 'published', ARRAY['analysis2DLecture1', 'analysis1DLecture3', 'analysis2DIntro', 'analysis2DLecture2', 'formalStatementsIntro', 'haloSoupSeminar', 'quantumLogicLecture2']::text[]),
  (8, 'fs_cauchy_riemann_symmetry', 'cauchy_riemann_symmetry', 'discrete_analysis', 'math', 'theorem', 7, 'theorem', NULL, 'math', 'law', 'shadow_map', 'Cauchy-Riemann Coordinate Symmetry', 'Equalities of partial derivatives underpinning hypercomplex conformal mappings.', '∂u/∂x = ∂v/∂y  ∧  ∂u/∂y = -∂v/∂x', 'theorem cauchy_riemann_orthogonality (u v : R_w → R_w → R_w) : du_dx = dv_dy ∧ du_dy = -dv_dx', NULL, 'published', ARRAY['analysis2DLecture1', 'analysis2DIntro']::text[]),
  (9, 'fs_contour_cauchy_goursat', 'contour_cauchy_goursat', 'discrete_analysis', 'math', 'theorem', 8, 'theorem', NULL, 'math', 'law', 'shadow_map', 'Hyperfinite Cauchy-Goursat Loop Vanishing', 'Sum of holomorphic increments along a closed discrete polygon collapses to zero.', '∮_γ f(z) dz = ∑_{k=0}^{N-1} f(z_k)·(z_{k+1} - z_k) ≃ 0', 'theorem cauchy_goursat_loop (f : C_w → C_w) (gamma : ClosedContour) : hyper_sum (eval_step f gamma) = 0', NULL, 'published', ARRAY['analysis2DLecture2', 'analysis2DIntro']::text[]),
  (10, 'fs_lee_yang_circle', 'lee_yang_circle', 'kinematics_and_dynamics', 'physics', 'theorem', 7, 'theorem', NULL, 'physics', 'law', 'shadow_map', 'The Lee-Yang Unit Circle Partition Theorem', 'All partition function zeros of ferromagnetic Ising systems lie precisely on the unit circle |z| = 1.', 'Z_N(z) = 0 ⟹ |z| = 1  in the complex fugacity plane', 'theorem lee_yang_circle (N : Nat) (z : C_w) (hZ : ising_partition N z = 0) : norm z = 1', NULL, 'published', ARRAY['analysis2DLecture3', 'analysis2DIntro']::text[]),
  (11, 'fs_harmonic_oscillator', 'harmonic_oscillator', 'kinematics_and_dynamics', 'physics', 'directed_equality', NULL, 'directed_equality', 10, 'physics', 'scenario', 'boundary_law', 'Harmonic Leapfrog Phase Space Orbit', 'Exact energy preservation in discrete symplectic integration of harmonic oscillators.', 'x(t + dt) = x(t) + v(t + dt/2)·dt  ∧  v(t + dt/2) = v(t - dt/2) - ω²·x(t)·dt', 'theorem harmonic_leapfrog_energy (x0 v0 omega dt : R_w) : leapfrog_energy x0 v0 = initial_energy', NULL, 'published', ARRAY['stemNewtonianBridge', 'vectorsLecture2', 'analysis2DIntro', 'analysis2DLecture3', 'vectorsLecture3']::text[]),
  (12, 'fs_three_polarizer_quantum', 'three_polarizer_quantum', 'kinematics_and_dynamics', 'physics', 'directed_equality', NULL, 'directed_equality', NULL, 'physics', 'scenario', 'shadow_map', 'Three-Polarizer Geometric Quantum Transmission', 'Quantum state projection through intermediate non-orthogonal polarization filters.', 'I = I₀ · cos²(θ₁) · cos²(θ₂ - θ₁)', 'theorem three_polarizer_transmission (I0 theta1 theta2 : R_w) : I_trans = I0 * (cos theta1)^2 * (cos (theta2 - theta1))^2', NULL, 'published', ARRAY['quantumLogicLecture1', 'quantumLogicLecture3', 'vectorsLecture3', 'quantumLogicLecture2']::text[]),
  (13, 'fs_hyperfinite_probability', 'hyperfinite_probability', 'information_and_signals', 'information', 'axiom', NULL, 'axiom', NULL, 'information', 'constitutional', 'shadow_map', 'Hyperfinite Normalized Probability Space', 'Uniform hyperfinite counting probability with infinitesimal resolution and no null sets.', 'P(A) = st(|A| / |Ω|)  where |Ω| = H ∈ *ℕ \ ℕ', 'theorem hyperfinite_probability_measure (Omega : HyperfiniteSampleSpace) (A : Event Omega) : P A = st (card A / card Omega)', NULL, 'published', ARRAY['bayesianInferenceLecture1', 'bayesianInferenceLecture4', 'quantumBayesianInferenceLecture1']::text[]),
  (14, 'fs_bayes_updating', 'bayes_updating', 'information_and_signals', 'information', 'directed_equality', 13, 'directed_equality', 14, 'information', 'law', 'shadow_map', 'Hyperfinite Bayesian Likelihood Inversion', 'Strictly positive hyperfinite updating preserving order under evidence accumulation.', 'P(H|E) = [P(E|H) · P(H)] / [P(E|H)·P(H) + P(E|¬H)·P(¬H)]', 'theorem bayes_rule (pH pE_H pE_notH : R_w) : p_posterior = (pE_H * pH) / (pE_H * pH + pE_notH * (1 - pH))', NULL, 'published', ARRAY['bayesianInferenceLecture2', 'bayesianInferenceLecture3', 'quantumBayesianInferenceLecture1', 'formalStatementsIntro']::text[]),
  (15, 'fs_tree2_totally_ordered', 'D_w_is_totally_ordered', 'discrete_analysis', 'math', 'theorem', NULL, 'theorem', 4, 'math', 'constitutional', 'conway_cut', 'Total Ordering on Conway Sign Sequences (Tree2)', 'Strict trichotomy and transitivity of Conway sign sequences representing Surreal dyadics.', '∀ x y ∈ Tree2, (x < y) ∨ (x = y) ∨ (y < x)', 'theorem Tree2.totally_ordered (x y : Tree2) : x < y ∨ x = y ∨ y < x', NULL, 'published', ARRAY['numbersLecture2']::text[]),
  (16, 'fs_ptolemaic_half_angle', 'dyadic_ptolemaic_sine', 'discrete_analysis', 'math', 'directed_equality', NULL, 'directed_equality', 12, 'math', 'scenario', 'conway_cut', 'Dyadic Ptolemaic Half-Angle Root Bisection', 'Algebraic calculation of sine and chord values via iterative nested square root bisections.', 'sin(θ/2) = √((1 - cos(θ)) / 2)', 'theorem ptolemaic_half_angle (theta : R_w) : sin (theta / 2) = sqrt ((1 - cos theta) / 2)', NULL, 'published', ARRAY['stemTrigFoundations', 'analysis1DLecture1']::text[]),
  (17, 'fs_standard_part_homomorphism', 'standard_part_homomorphism', 'discrete_analysis', 'math', 'theorem', NULL, 'theorem', NULL, 'math', 'constitutional', 'shadow_map', 'Standard Part Ring Homomorphism st(·)', 'Preservation of addition and multiplication under standard part shadow projection from finite ℝ_ω to ℝ.', 'st(x + y) = st(x) + st(y)  ∧  st(x · y) = st(x) · st(y)', 'theorem standard_part_is_homomorphism (x y : R_w_fin) : st (x + y) = st x + st y ∧ st (x * y) = st x * st y', NULL, 'published', ARRAY['analysis1DLecture1', 'analysis2DLecture1', 'vectorsLecture1', 'formalStatementsIntro', 'haloSoupSeminar']::text[]),
  (18, 'fs_cauchy_schwarz_discrete', 'cauchy_schwarz_discrete', 'discrete_analysis', 'math', 'theorem', NULL, 'theorem', NULL, 'math', 'law', 'boundary_law', 'Discrete Cauchy-Schwarz Inner Product Inequality', 'Fundamental geometric bound on hyperfinite Euclidean and Hilbert space projections.', '|⟨u, v⟩|² ≤ ⟨u, u⟩ · ⟨v, v⟩', 'theorem cauchy_schwarz_hyperfinite (u v : HyperVector N) : (inner_product u v)^2 ≤ inner_product u u * inner_product v v', NULL, 'published', ARRAY['vectorsLecture3', 'stemTrigFoundations']::text[]),
  (19, 'fs_polygonal_rim_chord', 'polygonal_rim_chord', 'discrete_analysis', 'math', 'directed_equality', NULL, 'directed_equality', 12, 'math', 'scenario', 'conway_cut', 'Dyadic Polygonal Rim Chord Law', 'Calculation of regular polygonal rim segment lengths on the discrete circle.', 'c_n = 2 · sin(π / n)', 'theorem rim_chord_length (n : Nat) : chord_len n = 2 * sin (pi / n)', NULL, 'published', ARRAY['stemTrigFoundations']::text[]),
  (20, 'fs_euler_identity_rotor', 'euler_identity_rotor', 'discrete_analysis', 'math', 'directed_equality', NULL, 'directed_equality', 12, 'math', 'constitutional', 'shadow_map', 'Euler Polar Rotor Decomposition', 'Representation of complex units as exponential orthogonal phase rotators.', 'e^{iθ} = cos(θ) + i · sin(θ)', 'theorem euler_rotor_identity (theta : R_w) : exp_i theta = Complex.mk (cos theta) (sin theta)', NULL, 'published', ARRAY['stemTrigFoundations', 'formalStatementsIntro']::text[]),
  (21, 'fs_unit_rotor_projection', 'unit_rotor_projection', 'discrete_analysis', 'math', 'directed_equality', 20, 'directed_equality', 12, 'math', 'scenario', 'shadow_map', 'Unit Rotor Sine & Cosine Projection', 'Orthogonal coordinate projection of 2D unit rotors under angle parameterization.', 'x = cos(θ),  y = sin(θ)  with  x² + y² = 1', 'theorem unit_rotor_norm (theta : R_w) : (cos theta)^2 + (sin theta)^2 = 1', NULL, 'published', ARRAY['stemTrigFoundations']::text[]),
  (22, 'fs_dyadic_isomorphism', 'Tree2_finite_is_dyad', 'discrete_analysis', 'math', 'axiom', 15, 'axiom', NULL, 'math', 'constitutional', 'conway_cut', 'The Core Dyadic Isomorphism Tree2 ≡ 𝔻', 'Order and ring isomorphism between sign-sequence trees and dyadic rationals.', 'Tree2(s) ≅ m / 2^n  ∧  Tree2 ↪ ℝ_ω', 'axiom Tree2_finite_is_dyad (t : Tree1) : Tree2_at (Tree1.toOrd t) = Dyad', NULL, 'published', ARRAY['numbersLecture2']::text[]),
  (23, 'fs_van_den_dries_ehrlich', 'No_eps0_totally_ordered', 'discrete_analysis', 'math', 'axiom', 15, 'axiom', NULL, 'math', 'constitutional', 'conway_cut', 'van den Dries–Ehrlich Subfield Theorem (2001)', 'Proof that the surreal numbers No(ε₀) formed at stage ε₀ constitute a real-closed field.', 'No(ε₀) is a real-closed field  ∧  No(ω) ⊂ No(ε₀) ⊂ No', 'axiom No_eps0_totally_ordered : TotalOrder No_eps0 No_eps0_le', NULL, 'published', ARRAY['numbersLecture2']::text[]),
  (24, 'fs_conway_addition', 'conway_addition', 'discrete_analysis', 'math', 'directed_equality', 15, 'directed_equality', 3, 'math', 'constitutional', 'conway_cut', 'Conway Inductive Addition (+)', 'Recursive bilateral addition on tree options choosing the simplest number born in the resulting cut gap.', 'x + y = { xᴸ + y, x + yᴸ | xᴿ + y, x + yᴿ }', 'def Conway.add (x y : Tree2) : Tree2', NULL, 'published', ARRAY['numbersLecture2']::text[]),
  (25, 'fs_conway_multiplication', 'conway_multiplication', 'discrete_analysis', 'math', 'directed_equality', 15, 'directed_equality', 7, 'math', 'constitutional', 'conway_cut', 'Conway Inductive Multiplication (·)', 'Recursive 4-way cross-product multiplication on tree options ensuring (x - xᴸ)(y - yᴸ) > 0.', 'x · y = { xᴸ·y + x·yᴸ - xᴸ·yᴸ, xᴿ·y + x·yᴿ - xᴿ·yᴿ | xᴸ·y + x·yᴿ - xᴸ·yᴿ, xᴿ·y + x·yᴸ - xᴿ·yᴸ }', 'def Conway.mul (x y : Tree2) : Tree2', NULL, 'published', ARRAY['numbersLecture2']::text[])
